// Cuentas de Sócrates. Para agregar otra: su subdominio, su token de Kommo, las etapas "delegadas" y la zona horaria.
return [{ json: { cuentas: {
  "landa": {
    "nombre": "Instituto Landa",
    "subdominio": "administracioninstitutolandacommx896",
    "token": "TOKEN_DE_KOMMO",
    "zona_horas": -6,
    "lookback_dias": 45,
    "agrupar_minutos": 60,
    "usuarios_excluidos": [],
    "max_leads": 400,
    "delegadas": [
      {
        "pipeline_id": 14248964,
        "status_id": 110028120,
        "nombre": "Preparatoria › Delegado Instituto Landa"
      },
      {
        "pipeline_id": 14248964,
        "status_id": 110028136,
        "nombre": "Preparatoria › Delegado Infinity Learning"
      },
      {
        "pipeline_id": 14508092,
        "status_id": 112064416,
        "nombre": "Infinity Learning IA › Delegado"
      },
      {
        "pipeline_id": 10360195,
        "status_id": 95211448,
        "nombre": "Embudo de ventas › Interés"
      }
    ]
  }
} } }];

// Sócrates: auditoría de respuesta a los leads que la IA pasa a un humano (pedido de Manu, 2-nov-2026).
// El flujo solo entrega los HECHOS por lead (cuándo lo delegó la IA y cuándo hubo cada toque humano); las reglas de 24 h / 48 h
// las aplica la página, así se pueden ajustar sin tocar este flujo.
// Delegado por la IA = el lead entra por primera vez a una etapa "delegada" y ese cambio lo hizo el sistema (created_by = 0).
// Toque humano = mensaje o llamada saliente, nota o tarea completada hecha por una persona (created_by distinto de 0).
// Los toques separados por menos de `agrupar_minutos` cuentan como uno (una ráfaga de mensajes no es un seguimiento).
const body = $('Webhook Sócrates').first().json.body || {};
const cfg = $('Config Sócrates').first().json;
const cuentaKey = String(body.cuenta || 'landa').toLowerCase();
const cta = (cfg.cuentas || {})[cuentaKey];
if (!cta) throw new Error('Cuenta no configurada: ' + cuentaKey);
const desde = body.desde || body.date_from;
const hasta = body.hasta || body.date_to;
if (!/^\d{4}-\d{2}-\d{2}$/.test(desde || '') || !/^\d{4}-\d{2}-\d{2}$/.test(hasta || '')) throw new Error('Faltan desde y hasta (AAAA-MM-DD).');

const OFF = (cta.zona_horas || 0) * 3600;                       // zona fija de la cuenta (México centro = -6)
const toStart = (d) => Math.floor(Date.parse(`${d}T00:00:00Z`) / 1000) - OFF;
const toEnd = (d) => Math.floor(Date.parse(`${d}T23:59:59Z`) / 1000) - OFF;
const fromTs = toStart(desde);
const toTs = toEnd(hasta);
if (toTs < fromTs) throw new Error('El periodo está al revés.');
if (toTs - fromTs > 62 * 86400) throw new Error('El periodo máximo es de 62 días.');
const ahora = Math.floor(Date.now() / 1000);
const LOOKBACK = (cta.lookback_dias || 45) * 86400;              // historial que se revisa para saber cuál fue la PRIMERA entrada
const AGRUP = (cta.agrupar_minutos || 60) * 60;
const MAX_LEADS = cta.max_leads || 400;

const headers = { Authorization: `Bearer ${cta.token}`, 'Content-Type': 'application/json' };
const base = `https://${cta.subdominio}.kommo.com/api/v4`;
const httpGet = async (url) => {
  let resp = await this.helpers.httpRequest({ method: 'GET', url, headers, json: true });
  if (!resp || typeof resp !== 'object') resp = {};            // Kommo regresa 204 sin cuerpo cuando no hay resultados
  return resp;
};
const paginar = async (url, clave, tope) => {
  const out = [];
  let u = url;
  let g = 0;
  while (u && g < tope) {
    const r = await httpGet(u);
    out.push(...((r._embedded && r._embedded[clave]) || []));
    u = (r._links && r._links.next && r._links.next.href) || null;
    g++;
  }
  return out;
};
const agregar = (qp) => (k, v) => qp.push(encodeURIComponent(k) + '=' + encodeURIComponent(v));

// Nombres de embudos, etapas y usuarios
const nombreEmbudo = {};
const nombreEtapa = {};
const pl = await httpGet(`${base}/leads/pipelines`);
for (const pp of ((pl._embedded && pl._embedded.pipelines) || [])) {
  nombreEmbudo[pp.id] = String(pp.name || '').trim();
  for (const st of ((pp._embedded && pp._embedded.statuses) || [])) nombreEtapa[st.id] = String(st.name || '').trim();
}
const users = await paginar(`${base}/users?limit=250`, 'users', 3);
const nombreUsuario = {};
users.forEach((u) => { nombreUsuario[u.id] = u.name; });
const excluidos = (cta.usuarios_excluidos || []).map(Number);
const personas = users.map((u) => Number(u.id)).filter((id) => !excluidos.includes(id));

// 1) Primera entrada de cada lead a una etapa delegada (historial de etapas)
const delegadas = cta.delegadas || [];
const qe = [];
const ae = agregar(qe);
ae('filter[type][0]', 'lead_status_changed');
ae('filter[created_at][from]', fromTs - LOOKBACK);
ae('filter[created_at][to]', toTs);
delegadas.forEach((o, i) => {
  ae(`filter[value_after][leads_statuses][${i}][pipeline_id]`, o.pipeline_id);
  ae(`filter[value_after][leads_statuses][${i}][status_id]`, o.status_id);
});
ae('limit', '100');
const eventosEntrada = await paginar(`${base}/events?${qe.join('&')}`, 'events', 60);
const primera = {};
for (const e of eventosEntrada) {
  const id = e.entity_id;
  if (id == null) continue;
  const d = e.value_after && e.value_after[0] && e.value_after[0].lead_status;
  if (!primera[id] || e.created_at < primera[id].ts) primera[id] = { ts: e.created_at, by: e.created_by || 0, etapa: d ? d.id : null, embudo: d ? d.pipeline_id : null };
}
// Cohorte: primera entrada dentro del periodo y hecha por el sistema (la IA)
const cohorteIds = Object.keys(primera).filter((id) => primera[id].ts >= fromTs && primera[id].ts <= toTs && primera[id].by === 0);
const entradasHumanas = Object.keys(primera).filter((id) => primera[id].ts >= fromTs && primera[id].ts <= toTs && primera[id].by !== 0).length;
cohorteIds.sort((a, b) => primera[b].ts - primera[a].ts);
const truncado = cohorteIds.length > MAX_LEADS;
const idsUsar = cohorteIds.slice(0, MAX_LEADS);

// 2) Datos de cada lead (con contactos)
const leads = [];
for (let i = 0; i < idsUsar.length; i += 50) {
  const lote = idsUsar.slice(i, i + 50);
  const q = ['limit=250', 'with=' + encodeURIComponent('contacts')];
  lote.forEach((id, k) => q.push(`filter%5Bid%5D%5B${k}%5D=${id}`));
  const r = await httpGet(`${base}/leads?${q.join('&')}`);
  leads.push(...((r._embedded && r._embedded.leads) || []));
}
const contactoDeLead = {};
const leadsDeContacto = {};
for (const l of leads) {
  const cs = (l._embedded && l._embedded.contacts) || [];
  const principal = cs.find((c) => c.is_main) || cs[0];
  if (principal) { contactoDeLead[l.id] = principal.id; (leadsDeContacto[principal.id] = leadsDeContacto[principal.id] || []).push(l.id); }
}

// 3) Toques humanos después de la entrega
const toques = {};
const marcar = (leadId, ts) => { (toques[leadId] = toques[leadId] || []).push(ts); };
if (leads.length && personas.length) {
  const minTs = Math.min(...leads.map((l) => primera[l.id].ts));
  const comunes = (qp) => {
    const a = agregar(qp);
    personas.forEach((h, i) => a(`filter[created_by][${i}]`, h));
    a('filter[created_at][from]', minTs);
    a('limit', '100');
    return a;
  };
  const idsLead = leads.map((l) => l.id);
  for (let i = 0; i < idsLead.length; i += 10) {
    const qp = [];
    const a = agregar(qp);
    a('filter[entity]', 'lead');
    a('filter[entity_id]', idsLead.slice(i, i + 10).join(','));
    ['common_note_added', 'task_completed'].forEach((t, k) => a(`filter[type][${k}]`, t));
    comunes(qp);
    const ev = await paginar(`${base}/events?${qp.join('&')}`, 'events', 10);
    for (const e of ev) marcar(e.entity_id, e.created_at);
  }
  const idsContacto = Object.keys(leadsDeContacto);
  for (let i = 0; i < idsContacto.length; i += 10) {
    const qp = [];
    const a = agregar(qp);
    a('filter[entity]', 'contact');
    a('filter[entity_id]', idsContacto.slice(i, i + 10).join(','));
    ['outgoing_chat_message', 'outgoing_call'].forEach((t, k) => a(`filter[type][${k}]`, t));
    comunes(qp);
    const ev = await paginar(`${base}/events?${qp.join('&')}`, 'events', 10);
    for (const e of ev) {
      if (e.entity_type === 'lead') marcar(e.entity_id, e.created_at);
      else for (const lid of (leadsDeContacto[e.entity_id] || [])) marcar(lid, e.created_at);
    }
  }
}
const agrupar = (arr) => {
  const out = [];
  let ultimo = null;
  for (const t of arr.slice().sort((a, b) => a - b)) { if (ultimo === null || t - ultimo > AGRUP) out.push(t); ultimo = t; }
  return out;
};
const iso = (t) => new Date(t * 1000).toISOString();

// 4) Respuesta: los hechos por lead
const salida = leads.map((l) => {
  const ent = primera[l.id];
  const despues = (toques[l.id] || []).filter((t) => t > ent.ts);
  return {
    id: l.id,
    nombre: l.name || ('Lead ' + l.id),
    asesor: nombreUsuario[l.responsible_user_id] || 'Sin responsable',
    embudo: nombreEmbudo[ent.embudo] || nombreEmbudo[l.pipeline_id] || ('Embudo ' + (ent.embudo || l.pipeline_id)),   // donde la IA lo entregó
    etapa_entrada: nombreEtapa[ent.etapa] || null,
    etapa_actual: (nombreEmbudo[l.pipeline_id] ? nombreEmbudo[l.pipeline_id] + ' › ' : '') + (nombreEtapa[l.status_id] || ('Etapa ' + l.status_id)),   // donde está hoy
    asignado_en: iso(ent.ts),
    contactos: agrupar(despues).map(iso),
    url: `https://${cta.subdominio}.kommo.com/leads/detail/${l.id}`,
  };
}).sort((a, b) => Date.parse(b.asignado_en) - Date.parse(a.asignado_en));

return [{ json: {
  cuenta: cuentaKey,
  periodo: { desde, hasta },
  generado: new Date().toISOString(),
  zona_horas: OFF / 3600,
  reglas: { contacto_horas: 24, seguimiento_horas: 48, agrupar_minutos: AGRUP / 60 },
  total: cohorteIds.length,
  truncado,
  descartados_movidos_por_personas: entradasHumanas,
  leads: salida,
  nota_metodologica: 'Lead de Sócrates = el que la IA (o una automatización) pasó por primera vez a una etapa delegada en el periodo: ' +
    delegadas.map((d) => d.nombre).join(', ') + '. Los que movió una persona no cuentan (' + entradasHumanas + ' en este periodo). ' +
    'Toque humano = WhatsApp o llamada saliente, nota o tarea completada hecha por una persona dentro de Kommo; lo que se escribe fuera de Kommo no aparece. ' +
    'Los toques separados por menos de ' + (AGRUP / 60) + ' min cuentan como uno. ' + (truncado ? 'Se muestran los ' + MAX_LEADS + ' más recientes.' : ''),
} }];
